import json
import math
import statistics
import sys
from pathlib import Path

out = Path(sys.argv[1])
dates = ["2024-03-01", "2024-03-04", "2024-03-05", "2024-03-06", "2024-03-07", "2024-03-08"]
closes = {
    "AAA": [100.0, 102.0, 99.0, 101.0, 104.0, 103.0],
    "BBB": [50.0, 49.5, 50.25, 51.0, 50.5, 52.0],
}
tickers = sorted(closes)
prices = {"dates": dates, "tickers": tickers, "closes": closes}

rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets}

w = 2
vol = {}
for t, r in rets.items():
    vol[t] = [
        None if i < w else statistics.stdev(r[i - w : i]) * math.sqrt(252) for i in range(len(r))
    ]
volseries = {"returns": returns, "window": w, "annualized": True, "values": vol}


def summary(t):
    r = rets[t]
    ar = 252 * statistics.fmean(r)
    av = math.sqrt(252) * statistics.stdev(r)
    return {
        "ticker": t,
        "ann_return": ar,
        "ann_vol": av,
        "sharpe": ar / av if av else 0.0,
        "last_vol": vol[t][-1],
    }


def drawdown(t):
    c = closes[t]
    peak_i, best = 0, (0.0, 0, 0)
    for i, x in enumerate(c):
        if x > c[peak_i]:
            peak_i = i
        d = x / c[peak_i] - 1
        if d < best[0]:
            best = (d, peak_i, i)
    return {"ticker": t, "depth": best[0], "peak_date": dates[best[1]], "trough_date": dates[best[2]]}


never = {"ticker": "CCC", "depth": 0.0, "peak_date": dates[0], "trough_date": dates[0]}
rows = []
for t in tickers:
    s, d = summary(t), drawdown(t)
    rows.append(
        {
            **s,
            "max_drawdown": d["depth"],
            "peak_date": d["peak_date"],
            "trough_date": d["trough_date"],
        }
    )

raw = [
    {"date": "2024-03-01", "ticker": "AAA", "close": 100.0},
    {"date": "2024-03-01", "ticker": "BBB", "close": 50.0},
    {"date": "2024-03-04", "ticker": "AAA", "close": 102.0},
    {"date": "2024-03-04", "ticker": "BBB", "close": None},
    {"date": "2024-03-05", "ticker": "BBB", "close": 50.25},
    {"date": "2024-03-05", "ticker": "AAA", "close": 99.0},
    {"date": "2024-03-06", "ticker": "AAA", "close": 101.0},
    {"date": "2024-03-06", "ticker": "BBB", "close": 51.0},
]

files = {
    "mdata.RawRow/sample.json": {"rows": raw},
    "mdata.Prices/sample.json": prices,
    "mdata.load_prices/sample.json": prices,
    "risk.Returns/sample.json": returns,
    "risk.VolSeries/sample.json": volseries,
    "risk.vol_series/sample.json": volseries,
    "risk.TickerSummary/sample.json": summary("AAA"),
    "risk.Drawdown/sample.json": {"drawdowns": [drawdown("AAA"), never]},
    "risk.Report/sample.json": {"path": "out/risk_report.json", "rows": rows},
}
for name, data in files.items():
    p = out / name
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(json.dumps(data, indent=2) + "\n")

csv = ["date,ticker,close"]
for i, d in enumerate(dates):
    for t in tickers:
        csv.append(f"{d},{t},{closes[t][i]}")
(out / "mdata.load_prices/prices.csv").write_text("\n".join(csv) + "\n")

